class Solution {
public:
    string minRemoveToMakeValid(string s) {
        // generated by Claude based on my semi pseudo code
        stack<int> ps; // pos of opening paren
        vector<int> ps_to_remove;
        for (int i = 0; i < (int)s.size(); i++) {
            if (s[i] == '(') {
                ps.push(i);
            } else if (s[i] == ')') {
                if (!ps.empty()) {
                    ps.pop();
                } else {
                    // i pos ')' has no match
                    ps_to_remove.push_back(i);
                }
            }
        }

        // if remained in ps, add them to ps_to_remove
        while (!ps.empty()) {
            ps_to_remove.push_back(ps.top());
            ps.pop();
        }
        // unmatched '(' and ')' positions are interleaved, so sort
        sort(ps_to_remove.begin(), ps_to_remove.end());

        string out;
        out.reserve(s.size());

        int last_s_pos = 0;
        for (int i : ps_to_remove) {
            // add [last_s_pos, i) into out
            out.append(s, last_s_pos, i - last_s_pos);
            last_s_pos = i + 1;
        }

        if (last_s_pos < (int)s.size()) {
            // add [last_s_pos, s.size()) into out
            out.append(s, last_s_pos, string::npos);
        }

        return out;
    }
};